WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_b_single'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '单独完工', 'kp-eng-b-single', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "单独完工问题"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "某人或某机器从头到尾独自完成一项工程。解题核心是“找最小公倍数赋值”。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题干只给出：“甲单独做需要 x 天，乙单独做需要 y 天”。这是赋值法的最典型场景。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "坚决抛弃设总量为1的习惯，采用特值法："}]}, {"type": "katexBlock", "attrs": {"content": "令 \\ W = LCM(T_1, T_2, ...) \\quad \\text{(LCM为最小公倍数)}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[提取各个主体单独完工的时间 T] --> B[求这些时间数字的最小公倍数]\nB --> C[将这个公倍数直接赋值给总工程量 W]\nC --> D[用 W 分别除以各自的时间 T, 得出每个人的效率 P]\nD --> E[根据题目后续的要求(如某人单独做几天)进行计算]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 修一条路，甲队单独修需要 12 天，乙队单独修需要 15 天。若甲队先修了 4 天后被调走，剩下的由乙队单独修完，乙队还需要几天？选项：A. 8  B. 9  C. 10  D. 12"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋值总量：12 和 15 的最小公倍数是 60。设总路长 W = 60。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "推导效率：甲每天修 P甲 = 60/12 = 5；乙每天修 P乙 = 60/15 = 4。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算已完成部分：甲先修了 4 天，完成工作量 = 4 × 5 = 20。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算剩余工作量：剩下 60 - 20 = 40 的工作量。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求乙的时间：乙单独修 40 的量，需要 40 ÷ P乙(4) = 10 天。选 C。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "生搬硬套公倍数：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果题目除了给时间，还给了一个具体的绝对数值（比如“这条路全长3000米”）。这时候千万不能再去自己赋值 W=60 了！有了真实数值必须用真实数值，特值法只适用于【全篇只有相对量(时间/比例)】的题目！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "背熟常见数字的最小公倍数：(10,15)->30; (12,15)->60; (20,30)->60; (12,15,20)->60。节约考场发呆的时间。"}]}]}$$ AS jsonb), NULL, '单独完工的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "单独完工"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_b_single", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
